Lemma wz_mod0 : forall x, x mod 18446744073709551616 = 0 -> Z_to_bv 64 x = Z_to_bv 64 0.
Proof.
  intros x Hx. apply bv_eq. rewrite !Z_to_bv_unsigned. unfold bv_wrap.
  change (bv_modulus 64) with 18446744073709551616. rewrite Hx. reflexivity.
Qed.

