(* [comment removed for export] *)
Definition dusc_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r v ctx first kti kid lo shi : Z) (S1 : svch) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (dusc_W lo sp r v) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ ARegistry LB m' r ctx v 0
    /\ rw_cells asegs m' v (SvcHdrCells (mkSVC (sv_vptr S1) kti kid (sv_owner S1) first (sv_destroy S1)))
    /\ ACONST m' /\ stack0 m' lo shi.

Lemma dusc_segB : asan_memcpy_stmt ->
  forall (r K v lo shi : Z) (LB : list block) (L : list svce) (S1 : svch) (ctx first kti kid kname : Z)
    (pcv sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s10 s11 t3 t4 t5 t6 : word) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 rax : word)
    (F : bvmap 5 word) fc (m : mem) (j0 j7 : list byte),
  (pcv = Z_to_bv 64 P_A_DUSC_RET \/ pcv = ret_pc (Z_to_bv 64 P_A_DUSC_RET)) ->
  rw_cells asegs m (bv_unsigned sp + -112) (dus_frame r 0 j0 j7 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs m v (SvcHdrCells S1) -> svch_ok S1 ->
  ARegistry LB m r ctx first 0 ->
  ro_cells asegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ati_ok m kti kname) ->
  ASvcChain m first L -> Forall (fun e => keys_match kti kid kname e = false) L ->
  Forall (fun e => (se_addr e + 48 <= r \/ r + SZ_REG <= se_addr e) /\ (se_addr e + 48 <= v \/ v + NEWSZ_SSVC <= se_addr e)) L ->
  bv_unsigned sp <= K -> K + 80 <= shi -> K mod 8 = 0 ->
  rblock_range v NEWSZ_SSVC -> addressable m v NEWSZ_SSVC -> shvis m v (v + NEWSZ_SSVC) ->
  (r + NEWSZ_REG <= v \/ v + NEWSZ_SSVC <= r) ->
  stk asegs m lo (bv_unsigned sp + -112) -> lo + 112 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv asegs m -> ACONST m -> stack0 m lo shi ->
  evt asegs (dusc_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r v ctx first kti kid lo shi S1 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2
             (Z_to_bv 64 (r + 56)) (Z_to_bv 64 K) (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (K + 8)) (Z_to_bv 64 0) (Z_to_bv 64 P_A_CREATE_SSVC) (Z_to_bv 64 (sv_owner S1)) (Z_to_bv 64 r) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (Z.shiftr (r + 56) 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr K 3)) s10 s11 t3 t4 t5 t6)
